DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY' OR Tag GLOB 'TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_CIV_TEXT_1','The Boundless City[NEWLINE]One expanding municipality with a finite workforce[NEWLINE]Science or Diplomacy; Domination through the special siege/subjugation rules[NEWLINE][NEWLINE]Grow one productive capital, expand connected territory, and assign real citizens to worthwhile jobs. The city can own a great deal of land, but ownership is not a substitute for workers, food or the engine''s workforce limits.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_CIV_TEXT_2','Choose strong capital food, production and defensible access. Improve the best nearby sites and establish the Registry. Let growth and culture expansion support one another instead of reserving every distant job immediately.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_CIV_TEXT_3','Review the Workforce''s actual food balance, assigned citizens and remote-job value. Build the infrastructure and Surveyors needed for the selected frontier. Prioritize jobs that improve the whole city rather than a distant tile''s isolated yield.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_CIV_TEXT_4','Support a conventional research or diplomatic plan with a mature capital. If seeking Domination, learn the reclaim, legal demolition and protected-capital subjugation rules; ordinary occupation and unlimited extra cities are not the plan.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_CIV_TEXT_5','- A large connected territory can offer a broad menu of jobs and resources.[NEWLINE]- Registry and Surveyor development reinforce frontier growth.[NEWLINE]- Capital-loss survival and special siege interactions provide alternatives to ordinary occupation.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_CIV_TEXT_6','- The capital and its supporting workforce are highly concentrated strategic assets.[NEWLINE]- Remote jobs still consume real population and obey implemented capacity limits.[NEWLINE]- Foreign-city acquisition and Domination use special rules rather than a normal expanding city empire.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_CIV_TEXT_7','- Contest important land before the contiguous border reaches it.[NEWLINE]- Raid productive approaches and threaten food or key assigned improvements.[NEWLINE]- Pressure the capital economy instead of assuming empty owned territory supplies unlimited output.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_CIV_TEXT_8','- Counting every owned tile as an automatically worked tile.[NEWLINE]- Expanding reservations without supporting food and population.[NEWLINE]- Expecting ordinary city capture to produce a permanent second municipal centre.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]McPvP: A closely watched single-city approach limits the number of distinct city objectives available in a match cycle; it does not prevent an objective from succeeding.[NEWLINE][NEWLINE]The Conical Union: A one-city plan does not depend on keeping several non-capital connection bonuses active, which helps in a map dominated by chokepoints and broken routes.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Luna Network: Fast settlement can claim useful land and constrain future contiguous expansion before it arrives.[NEWLINE][NEWLINE]The Filthy Realm: A city-targeted debuff affects a large portion of the municipality''s total output.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_CIV_HEADING_10','Implementation and timing limits');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_CIV_TEXT_10','Remote work remains subject to the documented native capacity and settlement boundaries. Use the Workforce and the engine-limit report as the authority for the currently supported jobs.');
