INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_LEADER_BACKGROUND','Grow one productive capital, expand connected territory, and assign real citizens to worthwhile jobs. The city can own a great deal of land, but ownership is not a substitute for workers, food or the engine''s workforce limits.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_LEADER_BACKGROUND',Text FROM Language_en_US WHERE Tag='TXT_KEY_BC_LEADER_PEDIA';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_STRATEGY','Grow one productive capital, expand connected territory, and assign real citizens to worthwhile jobs. The city can own a great deal of land, but ownership is not a substitute for workers, food or the engine''s workforce limits.[NEWLINE][NEWLINE]Choose strong capital food, production and defensible access. Improve the best nearby sites and establish the Registry. Let growth and culture expansion support one another instead of reserving every distant job immediately.[NEWLINE][NEWLINE]Review the Workforce''s actual food balance, assigned citizens and remote-job value. Build the infrastructure and Surveyors needed for the selected frontier. Prioritize jobs that improve the whole city rather than a distant tile''s isolated yield.[NEWLINE][NEWLINE]Support a conventional research or diplomatic plan with a mature capital. If seeking Domination, learn the reclaim, legal demolition and protected-capital subjugation rules; ordinary occupation and unlimited extra cities are not the plan.');
