INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_LEADER_TEXT_1','The Boundless City[NEWLINE]One expanding municipality with a finite workforce[NEWLINE]Science or Diplomacy; Domination through the special siege/subjugation rules[NEWLINE][NEWLINE]Grow one productive capital, expand connected territory, and assign real citizens to worthwhile jobs. The city can own a great deal of land, but ownership is not a substitute for workers, food or the engine''s workforce limits.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_LEADER_TEXT_2','Choose strong capital food, production and defensible access. Improve the best nearby sites and establish the Registry. Let growth and culture expansion support one another instead of reserving every distant job immediately.[NEWLINE][NEWLINE]Review the Workforce''s actual food balance, assigned citizens and remote-job value. Build the infrastructure and Surveyors needed for the selected frontier. Prioritize jobs that improve the whole city rather than a distant tile''s isolated yield.[NEWLINE][NEWLINE]Support a conventional research or diplomatic plan with a mature capital. If seeking Domination, learn the reclaim, legal demolition and protected-capital subjugation rules; ordinary occupation and unlimited extra cities are not the plan.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEBOUNDLESSCITY_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]McPvP: A closely watched single-city approach limits the number of distinct city objectives available in a match cycle; it does not prevent an objective from succeeding.[NEWLINE][NEWLINE]The Conical Union: A one-city plan does not depend on keeping several non-capital connection bonuses active, which helps in a map dominated by chokepoints and broken routes.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Luna Network: Fast settlement can claim useful land and constrain future contiguous expansion before it arrives.[NEWLINE][NEWLINE]The Filthy Realm: A city-targeted debuff affects a large portion of the municipality''s total output.');
